const now=()=>Date.now(),dayKey=(d)=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const mins=ms=>{const m=Math.floor(ms/60000);return m>=60?`${Math.floor(m/60)}時間${m%60}分`:`${m}分`};const normalize=s=>String(s??'').normalize('NFKC').trim().replace(/\s+/g,'').toLowerCase().replace(/[，、]/g,',').replace(/度$/,'');
function setTheme(key){theme=THEMES[key]?key:'aurora';store('studyos_theme',theme);const t=THEMES[theme];for(const [k,v] of Object.entries(t)){if(['name','scheme'].includes(k))continue;document.documentElement.style.setProperty('--'+(k==='accentText'?'accentText':k),v)}document.documentElement.style.setProperty('--accent',accentOverride||t.accent);document.documentElement.style.colorScheme=t.scheme;$('accentColor').value=accentOverride||t.accent;renderThemes()}
function renderThemes(){const grid=$('themeGrid');grid.replaceChildren();for(const [key,t] of Object.entries(THEMES)){const b=document.createElement('button');b.className='theme-option'+(key===theme?' selected':'');b.innerHTML=`<div class="theme-swatch"><span></span><span></span><span></span></div><strong>${t.name}</strong><small>${key==='aurora'?'幻想的な光':key==='luxury'?'落ち着いた高級感':key==='clean'?'明るくシンプル':key==='glass'?'透明感':key==='cosmic'?'宇宙のような深い青':'モノクロ'}</small>`;b.querySelector('.theme-swatch').style.background=t.bg;b.querySelectorAll('.theme-swatch span').forEach((x,i)=>x.style.background=i===0?t.accent:t.panel2);b.onclick=()=>{accentOverride=null;store('studyos_accent',null);setTheme(key)};grid.append(b)}}
