function page(id){document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id===id));document.querySelectorAll('#nav button').forEach(el=>el.classList.toggle('active',el.dataset.page===id));$('pageTitle').textContent=titles[id];window.scrollTo(0,0);if(id==='home')renderHome();if(id==='collections')renderCollections();if(id==='pastmanager')renderPastLibrary();if(id==='analytics'){renderAnalytics();renderEndlessSummary();}if(id==='endless')renderEndless();if(id==='timer')$('timerToday').textContent=mins(totalMs(dayKey(now())))}
function setMode(m){mode=m;for(const [id,val] of [['studyMode','study'],['testMode','test'],['certMode','cert']])$(id).classList.toggle('selected',m===val);$('certOptions').classList.toggle('hidden',m!=='cert');$('subjectPanel').classList.toggle('hidden',m==='cert');$('testTimeWrap').classList.toggle('hidden',m==='study'&&certAction!=='past');$('formatWrap').classList.toggle('hidden',m!=='study');$('modeHint').textContent=m==='study'?'学習は選択式・入力式・混合式から選択。': 'テストは入力式。時間指定または無制限を選べます。';renderWizard();refreshAvailability()}
function options(select,values){select.replaceChildren();for(const [value,label] of values){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}}
function updateLevels(){const s=$('subject').value;const catalog=CURRICULUM[s]||{};const existing=[...new Set(sourceBank().filter(q=>q.subject===s).map(q=>q.level))];const levels=[...new Set([...Object.keys(catalog),...existing])];options($('level'),[['all','すべて'],...levels.map(x=>[x,x])]);updateUnits()}
function updateUnits(){const s=$('subject').value,l=$('level').value;const catalog=CURRICULUM[s]||{};const units=l==='all'?Object.values(catalog).flat():catalog[l]||[];const existing=sourceBank().filter(q=>q.subject===s&&(l==='all'||q.level===l)).map(q=>q.unit);options($('unit'),[['all','すべて'],...[...new Set([...units,...existing])].map(x=>[x,x])]);refreshAvailability()}
function pool(){if(mode==='cert'){const type=$('certType').value,grade=$('certGrade').value;return [...BANK,...customQuestions,...pastExams.filter(q=>q.addStandard!==false&&q.answer&&q.question)].filter(q=>q.subject===type&&q.answer&&(q.certGrade===grade||q.level===({math:'数検',english:'英検',japanese:'漢検',it:''}[type]||'')+grade||q.level===grade)).filter((q,i,a)=>a.findIndex(x=>questionId(x)===questionId(q))===i)}return sourceBank().filter(q=>q.subject===$('subject').value&&($('level').value==='all'||q.level===$('level').value)&&($('unit').value==='all'||q.unit===$('unit').value))}
function refreshAvailability(){const n=certAction==='past'&&mode==='cert'?pastSelectedQuestions().length:pool().length;$('availability').textContent=`この範囲で利用できる問題：${n}問（指定数より少ない場合は利用可能な問題数で出題）`;$('startQuiz').disabled=!n}
function startQuiz(){if(mode!=='study'&&!unlimitedTime&&(!Number.isInteger(Number($('testMinutes').value))||Number($('testMinutes').value)<1||Number($('testMinutes').value)>1440)){alert('制限時間は1〜1440分の整数で入力してください。');return}if(timerElapsed()>1000){pauseTimer();sessions.unshift({date:now(),subject:$('timerSubject').value,ms:timer.elapsed,source:'timer'});store('studyos_sessions',sessions);resetTimer()}const questions=mode==='cert'&&certAction==='past'?pastSelectedQuestions():weightedPick(augmentStandardPool(pool()),Number($('count').value));if(!questions.length)return;quiz={mode,format:mode!=='study'?'input':$('format').value,questions,answers:Array(questions.length).fill(''),index:0,checked:Array(questions.length).fill(false),started:now(),activeStart:now(),elapsed:0,deadline:mode==='study'||unlimitedTime?null:now()+Number($('testMinutes').value)*60000};saveDraft();page('quiz');showQuestion()}
function saveDraft(){if(quiz)store('studyos_draft',{...quiz,activeStart:null})}
function quizTime(){if(!quiz)return 0;return quiz.elapsed+(quiz.activeStart?now()-quiz.activeStart:0)}
function showQuestion(){if(!quiz)return;if(quiz.deadline&&now()>=quiz.deadline){finishQuiz(true);return}const q=quiz.questions[quiz.index],i=quiz.index,locked=quiz.mode==='study'&&quiz.checked[i],format=quiz.mode!=='study'?'input':quiz.format==='mixed'?(i%2?'input':'choice'):quiz.format;$('quizLabel').textContent=`${NAMES[q.subject]} / ${q.level} / ${q.unit} · ${quiz.mode==='study'?'学習':quiz.mode==='cert'?'検定':'テスト'}`;$('quizProgress').textContent=`${i+1} / ${quiz.questions.length}`;$('progressFill').style.width=`${(i+1)/quiz.questions.length*100}%`;$('question').textContent=q.question||'画像の問題を確認して回答してください';renderQuestionMedia(q);const area=$('answerArea');area.replaceChildren();if(format==='choice'){const wrap=document.createElement('div');wrap.className='answers';(q.choices?.length?q.choices:[q.answer||'正解未登録']).forEach((c,j)=>{const b=document.createElement('button');b.className='answer-option'+(quiz.answers[i]===c?' selected':'');b.textContent=`${j+1}. ${c}`;b.disabled=locked;b.onclick=()=>{quiz.answers[i]=c;saveDraft();showQuestion()};wrap.append(b)});area.append(wrap)}else{const inp=document.createElement('input');inp.type='text';inp.placeholder='ここに回答を入力';inp.autocomplete='off';inp.value=quiz.answers[i];inp.disabled=locked;inp.oninput=()=>{quiz.answers[i]=inp.value;saveDraft()};inp.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();nextQuestion()}};area.append(inp)}const fb=$('feedback');fb.className='';fb.textContent='';if(locked){const ok=!!q.answer&&normalize(quiz.answers[i])===normalize(q.answer);fb.className=ok?'good':'bad';fb.textContent=q.answer?`${ok?'正解！':'正解：'+q.answer}\n${q.explanation||''}`:'正解未登録：終了後に自己採点してください。'}$('prevQuestion').disabled=i===0||quiz.mode==='study';$('skipQuestion').disabled=locked;$('nextQuestion').textContent=quiz.mode!=='study'?(i===quiz.questions.length-1?'回答を確認 →':'次へ →'):(locked?(i===quiz.questions.length-1?'結果を見る →':'次の問題へ →'):'回答を確定 →');const dots=$('questionDots');dots.replaceChildren();quiz.questions.forEach((_,j)=>{const b=document.createElement('button');b.textContent=j+1;b.className=(j===i?'current ':'')+(quiz.answers[j]?'answered':'');b.disabled=quiz.mode==='study'&&j!==i;b.onclick=()=>{quiz.index=j;saveDraft();showQuestion()};dots.append(b)})}
function nextQuestion(){if(!quiz)return;const i=quiz.index;if(quiz.mode==='study'&&!quiz.checked[i]){quiz.checked[i]=true;saveDraft();showQuestion();return}if(i===quiz.questions.length-1){if(quiz.mode!=='study')showReview();else finishQuiz();return}quiz.index++;saveDraft();showQuestion()}
function showReview(){if(quiz?.deadline&&now()>=quiz.deadline){finishQuiz(true);return}page('review');const answered=quiz.answers.filter(x=>normalize(x)).length;$('reviewSummary').textContent=`回答済み ${answered}問 / 未回答 ${quiz.questions.length-answered}問`;const grid=$('reviewGrid');grid.replaceChildren();quiz.questions.forEach((q,i)=>{const b=document.createElement('button');b.textContent=i+1;b.className=quiz.answers[i]?'answered':'';b.title=quiz.answers[i]?'回答済み':'未回答';b.onclick=()=>{quiz.index=i;page('quiz');showQuestion()};grid.append(b)})}
function finishQuiz(timedOut=false){if(!quiz)return;quiz.elapsed=quizTime();quiz.activeStart=null;const correct=quiz.questions.filter((q,i)=>!!q.answer&&normalize(quiz.answers[i])===normalize(q.answer)).length;quiz.questions.forEach((q,i)=>{const id=questionId(q);const st=questionStats[id]||{correct:0,wrong:0,skipped:0};if(!normalize(quiz.answers[i]))st.skipped++;else if(q.answer&&normalize(quiz.answers[i])===normalize(q.answer))st.correct++;else st.wrong++;questionStats[id]=st});store('studyos_question_stats',questionStats);const unanswered=quiz.answers.filter(a=>!normalize(a)).length;const rec={id:now(),date:now(),kind:quiz.mode,subject:quiz.questions[0].subject,total:quiz.questions.length,correct,unanswered,format:quiz.format,elapsed:quiz.elapsed};records.unshift(rec);store('studyos_records',records);sessions.unshift({date:rec.date,subject:rec.subject,ms:rec.elapsed,source:quiz.mode});store('studyos_sessions',sessions);$('resultTitle').textContent=timedOut?'時間切れ・自動採点':quiz.mode==='study'?'学習完了':quiz.mode==='cert'?'検定練習結果':'テスト結果';$('resultStats').textContent=`${correct} / ${quiz.questions.length} 正解 · 正答率 ${Math.round(correct/quiz.questions.length*100)}% · 未回答 ${unanswered}問`;const list=$('resultList');list.replaceChildren();quiz.questions.forEach((q,i)=>{const ok=!!q.answer&&normalize(quiz.answers[i])===normalize(q.answer);const item=document.createElement('div');item.className='result-item '+(ok?'good':'bad');const h=document.createElement('strong');h.textContent=`${i+1}. ${q.question}`;const a=document.createElement('p');a.textContent=`あなたの回答：${quiz.answers[i]||'未回答'} / 正解：${q.answer}`;const e=document.createElement('p');e.className='muted';e.textContent=q.explanation;item.append(h,a,e);if(q.image){const media=document.createElement(q.imageType==='application/pdf'?'iframe':'img');media.src=q.image;media.className=q.imageType==='application/pdf'?'problem-pdf':'problem-image';item.append(media)}if(q.answerImage){const note=document.createElement('p');note.textContent='解答資料：';item.append(note);const media=document.createElement(q.answerImageType==='application/pdf'?'iframe':'img');media.src=q.answerImage;media.className=q.answerImageType==='application/pdf'?'problem-pdf':'problem-image';item.append(media)}list.append(item)});quiz=null;localStorage.removeItem('studyos_draft');page('result')}
function totalMs(key=null){return sessions.filter(s=>!key||dayKey(s.date)===key).reduce((sum,s)=>sum+Math.max(0,Number(s.ms)||0),0)}
function renderHistory(el,items){el.replaceChildren();if(!items.length){el.textContent='まだ記録がありません。';el.classList.add('muted');return}el.classList.remove('muted');items.forEach(r=>{const div=document.createElement('div');div.className='history-item';const date=new Date(r.date).toLocaleDateString('ja-JP',{month:'numeric',day:'numeric'});div.innerHTML=`<span>${r.kind==='test'?'テスト':'学習'} · ${NAMES[r.subject]||r.subject}<br><small>${date} · ${r.total}問 · ${mins(r.elapsed)}</small></span><strong>${r.correct}/${r.total}</strong>`;el.append(div)})}
function renderHome(){$('homeTotal').textContent=mins(totalMs());$('homeToday').textContent=mins(totalMs(dayKey(now())));$('homeQuestions').textContent=records.reduce((a,r)=>a+r.total,0);const tests=records.filter(r=>r.kind==='test');$('homeAccuracy').textContent=tests.length?Math.round(tests.reduce((a,r)=>a+r.correct,0)/tests.reduce((a,r)=>a+r.total,0)*100)+'%':'—';renderHistory($('recentHome'),records.slice(0,5))}
function renderAnalytics(){const today=new Date();today.setHours(0,0,0,0);const n=period==='day'?1:period==='week'?7:30;const dates=Array.from({length:n},(_,i)=>{const d=new Date(today);d.setDate(today.getDate()-(n-1-i));return d});const values=dates.map(d=>totalMs(dayKey(d)));const sum=values.reduce((a,b)=>a+b,0);$('periodTotal').textContent=mins(sum);$('periodAverage').textContent=mins(sum/n);$('allTime').textContent=mins(totalMs());$('studyDays').textContent=new Set(sessions.filter(s=>s.ms>0).map(s=>dayKey(s.date))).size+'日';const chart=$('activityChart');chart.replaceChildren();const max=Math.max(...values,60000);dates.forEach((d,i)=>{const c=document.createElement('div');c.className='bar-col';const bar=document.createElement('div');bar.className='bar';bar.style.height=Math.max(2,values[i]/max*165)+'px';bar.title=mins(values[i]);const label=document.createElement('small');label.textContent=period==='day'?'今日':period==='week'?['日','月','火','水','木','金','土'][d.getDay()]:i%5===0?`${d.getMonth()+1}/${d.getDate()}`:'';c.append(bar,label);chart.append(c)});const bars=$('subjectBars');bars.replaceChildren();const bySubject={};sessions.forEach(s=>{bySubject[s.subject]=(bySubject[s.subject]||0)+s.ms});const all=Object.values(bySubject).reduce((a,b)=>a+b,0);Object.entries(bySubject).sort((a,b)=>b[1]-a[1]).forEach(([s,ms])=>{const row=document.createElement('div');row.className='subject-row';const top=document.createElement('div');const name=document.createElement('span');name.textContent=NAMES[s]||s;const val=document.createElement('span');val.textContent=mins(ms);top.append(name,val);const track=document.createElement('div');track.className='subject-track';const fill=document.createElement('div');fill.style.width=(all?ms/all*100:0)+'%';track.append(fill);row.append(top,track);bars.append(row)});if(!all)bars.textContent='学習時間の記録はまだありません。';renderHistory($('allHistory'),records.slice(0,30))}
// タイマー: 1秒ごとに実時間との差から表示。ページを閉じる前の確定記録のみ保存。
let timer={type:'stopwatch',running:false,elapsed:0,started:0,target:25*60000};let timerInterval=null;
function timerElapsed(){return timer.elapsed+(timer.running?now()-timer.started:0)}
function renderTimer(){const elapsed=timerElapsed(),remain=timer.type==='countdown'?Math.max(0,timer.target-elapsed):elapsed,secs=Math.floor(remain/1000);$('timerDisplay').textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;$('timerState').textContent=timer.running?'集中中':elapsed?'一時停止':'準備完了';$('timerStart').textContent=timer.running?'一時停止':elapsed?'再開':'開始';$('timerRing').style.strokeDashoffset=timer.type==='countdown'?578*Math.min(1,elapsed/timer.target):0;if(timer.type==='countdown'&&timer.running&&elapsed>=timer.target){timer.elapsed=timer.target;timer.running=false;renderTimer();alert('設定時間が終了しました。記録して終了を押してください。')}}
function pauseTimer(){if(timer.running){timer.elapsed=timerElapsed();timer.running=false}renderTimer()}
function resetTimer(){pauseTimer();timer.elapsed=0;renderTimer()}
function timerMode(type){pauseTimer();timer.type=type;timer.elapsed=0;timer.target=Math.max(1,Math.min(240,Number($('duration').value)||25))*60000;$('durationWrap').classList.toggle('hidden',type!=='countdown');$('stopwatchMode').classList.toggle('selected',type==='stopwatch');$('countdownMode').classList.toggle('selected',type==='countdown');renderTimer()}
function saveTimer(){pauseTimer();if(timer.elapsed<1000){alert('記録する時間がありません。');return}sessions.unshift({date:now(),subject:$('timerSubject').value,ms:timer.elapsed,source:'timer'});store('studyos_sessions',sessions);resetTimer();$('timerToday').textContent=mins(totalMs(dayKey(now())));alert('勉強時間を記録しました。')}
function init(){const date=new Date();$('today').textContent=date.toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric',weekday:'short'});options($('subject'),Object.entries(NAMES));options($('timerSubject'),Object.entries(NAMES));options($('importSubject'),Object.entries(NAMES));$('questionSource').onchange=()=>{refreshBookFilter();updateLevels()};$('bookFilter').onchange=updateLevels;$('subject').onchange=()=>{updateLevels();renderSubjectCards();renderUnitCards()};$('level').onchange=()=>{updateUnits();renderUnitCards()};$('unit').onchange=()=>{refreshAvailability();renderUnitCards()};$('studyMode').onclick=()=>{setMode('study');setWizardStep(1)};$('testMode').onclick=()=>{setMode('test');setWizardStep(1)};$('certMode').onclick=()=>{setMode('cert');setWizardStep(1)};options($('certType'),Object.entries(CERTS).map(([k,v])=>[k,v.name]));$('certType').onchange=()=>{const c=CERTS[$('certType').value];options($('certGrade'),c.grades.map(x=>[x,x]));refreshAvailability();renderPastExamList()};$('certGrade').onchange=()=>{refreshAvailability();renderPastExamList()};$('certType').onchange();$('startQuiz').onclick=startQuiz;initV6();$('prevQuestion').onclick=()=>{if(quiz&&quiz.index>0){quiz.index--;saveDraft();showQuestion()}};$('nextQuestion').onclick=nextQuestion;$('skipQuestion').onclick=()=>{if(!quiz)return;quiz.answers[quiz.index]='';if(quiz.mode==='study'){quiz.checked[quiz.index]=true;saveDraft();showQuestion()}else nextQuestion()};$('quitQuiz').onclick=()=>{if(confirm('中断しますか？ この学習の途中結果は保存されません。')){quiz=null;localStorage.removeItem('studyos_draft');page('home')}};$('submitTest').onclick=()=>finishQuiz();$('backToQuiz').onclick=()=>{page('quiz');showQuestion()};document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>{if(quiz&&!confirm('学習を中断しますか？（途中の回答は一時保存されます）'))return;if(quiz){quiz.elapsed=quizTime();quiz.activeStart=null;saveDraft();quiz=null}page(b.dataset.page)});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(b.dataset.mode){setMode(b.dataset.mode);setWizardStep(1)}else if(b.dataset.go==='setup')setWizardStep(0);page(b.dataset.go)});document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('selected',x===b));renderAnalytics()});$('stopwatchMode').onclick=()=>timerMode('stopwatch');$('countdownMode').onclick=()=>timerMode('countdown');$('duration').onchange=()=>{if(!timer.running)timerMode('countdown')};$('timerStart').onclick=()=>{if(quiz){alert('問題演習中は自動で学習時間を計測しています。');return}if(timer.running)pauseTimer();else{timer.started=now();timer.running=true}renderTimer()};$('timerReset').onclick=resetTimer;$('timerSave').onclick=saveTimer;timerInterval=setInterval(()=>{renderTimer();if(quiz?.deadline){const left=Math.max(0,quiz.deadline-now());$('quizCountdown').classList.remove('hidden');$('quizCountdown').textContent='残り '+Math.floor(left/60000)+':'+String(Math.floor(left/1000)%60).padStart(2,'0');if(left===0)finishQuiz(true)}else $('quizCountdown').classList.add('hidden')},300);$('accentColor').oninput=e=>{accentOverride=e.target.value;store('studyos_accent',accentOverride);document.documentElement.style.setProperty('--accent',accentOverride)};$('exportData').onclick=()=>{const data=JSON.stringify({version:6,records,sessions,theme,accentOverride,books,customQuestions,questionStats,endlessData,standardGenerated,pastExams},null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download='studyos-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('importData').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.records)||!Array.isArray(data.sessions))throw Error('形式が違います');if(!confirm('現在の学習履歴をインポートしたデータで置き換えますか？'))return;records=data.records;sessions=data.sessions;books=Array.isArray(data.books)?data.books:books;customQuestions=Array.isArray(data.customQuestions)?data.customQuestions:customQuestions;questionStats=data.questionStats||questionStats;if(data.endlessData){endlessData=data.endlessData;endlessPersist()}if(Array.isArray(data.pastExams)){pastExams=data.pastExams;store('studyos_past_exams_v6',pastExams)}if(Array.isArray(data.standardGenerated)){standardGenerated=data.standardGenerated;store('studyos_generated_standard_v5',standardGenerated)}store('studyos_books',books);store('studyos_custom_questions',customQuestions);store('studyos_question_stats',questionStats);renderCollections();refreshBookFilter();store('studyos_records',records);store('studyos_sessions',sessions);renderHome();alert('インポートしました')}catch{alert('読み込めないファイルです。')}e.target.value=''};refreshBookFilter();updateLevels();setMode('study');setTheme(theme);renderTimer();renderHome();const draft=read('studyos_draft',null);if(draft&&draft.questions?.length&&confirm('前回中断した問題を再開しますか？')){quiz={...draft,activeStart:now()};page('quiz');showQuestion()}else localStorage.removeItem('studyos_draft')}
window.addEventListener('pagehide',()=>{if(quiz){quiz.elapsed=quizTime();quiz.activeStart=null;saveDraft()}});

// v3: ローカル問題集と画像・PDF資料の保存。自動OCRは未実装。
function persistCustom(){try{store('studyos_books',books);store('studyos_custom_questions',customQuestions);return true}catch(e){alert('保存容量が足りません。画像を小さくするか、不要な問題を削除してください。');return false}}
function questionId(q){return String(q.id??[q.subject,q.level,q.unit,q.question].join('|'))}
function sourceBank(){const source=$('questionSource')?.value||'standard';const book=$('bookFilter')?.value||'all';const custom=customQuestions.filter(q=>book==='all'||q.bookIds?.includes(book));const standard=[...BANK,...customQuestions.filter(q=>q.addStandard),...pastExams.filter(q=>q.addStandard!==false&&q.answer&&q.question)];if(source==='standard')return standard;if(source==='uploaded')return custom;return [...BANK,...customQuestions.filter(q=>q.addStandard||book==='all'||q.bookIds?.includes(book)),...pastExams.filter(q=>q.addStandard!==false&&q.answer&&q.question)].filter((q,i,a)=>a.findIndex(x=>questionId(x)===questionId(q))===i)}
function weightedPick(pool,count){const candidates=[...pool],out=[];while(candidates.length&&out.length<count){const weights=candidates.map(q=>{const s=questionStats[questionId(q)]||{correct:0,wrong:0,skipped:0};return Math.max(1,5+3*s.wrong+4*s.skipped-2*s.correct)});const total=weights.reduce((a,b)=>a+b,0);let r=Math.random()*total;let idx=weights.findIndex(w=>(r-=w)<0);if(idx<0)idx=0;out.push(candidates.splice(idx,1)[0])}return out}
function refreshBookFilter(){const old=$('bookFilter').value;options($('bookFilter'),[['all','すべての問題集'],...books.map(b=>[b.id,b.name])]);if(books.some(b=>b.id===old))$('bookFilter').value=old;$('bookFilterWrap').classList.toggle('hidden',$('questionSource').value==='standard')}
function renderCollections(){const grid=$('bookGrid');grid.replaceChildren();for(const b of books){const tile=document.createElement('div');tile.className='book-tile';const title=document.createElement('h4');title.textContent='▣ '+b.name;const count=document.createElement('p');count.className='muted';count.textContent=customQuestions.filter(q=>q.bookIds?.includes(b.id)).length+'問';const actions=document.createElement('div');actions.className='book-actions';for(const [label,action] of [['学習',()=>launchBook(b.id,'study')],['テスト',()=>launchBook(b.id,'test')],['名前変更',()=>renameBook(b.id)],['削除',()=>deleteBook(b.id)]]){const btn=document.createElement('button');btn.className='outline';btn.textContent=label;btn.onclick=action;actions.append(btn)}tile.append(title,count,actions);grid.append(tile)}if(!books.length)grid.textContent='問題集がありません。「新しい問題集」から作成してください。';options($('bookTarget'),books.map(b=>[b.id,b.name]));$('customCount').textContent=customQuestions.length+'問';const list=$('customList');list.replaceChildren();customQuestions.forEach(q=>{const row=document.createElement('div');row.className='custom-row';const info=document.createElement('div');const name=document.createElement('strong');name.textContent=q.question?.slice(0,65)||'画像問題';const sub=document.createElement('p');sub.className='muted';sub.textContent=[NAMES[q.subject],q.level,q.unit].filter(Boolean).join(' / ');info.append(name,sub);const actions=document.createElement('div');actions.className='book-actions';const edit=document.createElement('button');edit.className='outline';edit.textContent='編集';edit.onclick=()=>editProblem(q.id);const del=document.createElement('button');del.className='outline';del.textContent='削除';del.onclick=()=>{if(confirm('この問題を完全に削除しますか？')){customQuestions=customQuestions.filter(x=>x.id!==q.id);persistCustom();renderCollections();updateLevels()}};actions.append(edit,del);row.append(info,actions);list.append(row)});refreshBookFilter()}
function launchBook(id,m){$('questionSource').value='uploaded';refreshBookFilter();$('bookFilter').value=id;updateLevels();setMode(m);page('setup')}
function renameBook(id){const b=books.find(x=>x.id===id);if(!b)return;const name=prompt('問題集の新しい名前',b.name)?.trim();if(name){b.name=name;persistCustom();renderCollections()}}
function deleteBook(id){const b=books.find(x=>x.id===id);if(!b||!confirm(`「${b.name}」を削除しますか？ 問題は他の問題集に所属していれば残ります。`))return;books=books.filter(x=>x.id!==id);customQuestions.forEach(q=>q.bookIds=q.bookIds.filter(x=>x!==id));customQuestions=customQuestions.filter(q=>q.bookIds.length||q.addStandard);persistCustom();renderCollections();updateLevels()}
let editingId=null;
function editProblem(id){const q=customQuestions.find(x=>x.id===id);if(!q)return;editingId=id;$('bookTarget').value=q.bookIds?.[0]||'';$('importSubject').value=q.subject;$('importLevel').value=q.level;$('importUnit').value=q.unit;$('addStandard').checked=!!q.addStandard;$('problemText').value=q.question;$('problemAnswer').value=q.answer;$('problemExplanation').value=q.explanation;$('saveProblem').textContent='変更を保存';$('importStatus').textContent='編集中：既存の画像資料は変更しない限り保持します。';page('collections')}
function renderQuestionMedia(q){const holder=$('questionMedia');holder.replaceChildren();if(!q.image)return;const media=document.createElement(q.imageType==='application/pdf'?'iframe':'img');media.src=q.image;media.className=q.imageType==='application/pdf'?'problem-pdf':'problem-image';media.title='問題資料';holder.append(media)}
