// 標準学習専用の検証可能な問題生成。問題ごとの履歴は従来の questionStats に記録。
let standardGenerated=read('studyos_generated_standard_v5',[]);
function augmentStandardPool(base){
 if(mode==='cert'||$('questionSource').value==='uploaded'||$('subject').value!=='math')return base;
 const level=$('level').value,unit=$('unit').value;
 const eligible=q=>(level==='all'||q.level===level)&&(unit==='all'||q.unit===unit);
 const pool=[...base,...standardGenerated.filter(eligible)];
 for(let i=0;i<Math.min(15,Number($('count').value));i++){
  let q=null;for(let tries=0;tries<20;tries++){const candidate=verifiedGeneratedQuestion();if(eligible(candidate)&&!pool.some(x=>eNorm(x.question)===eNorm(candidate.question)&&x.subject==='math')){q=candidate;break}}
  if(q){q.id='std|'+q.question;standardGenerated.push(q);pool.push(q)}
 }
 if(standardGenerated.length>500)standardGenerated=standardGenerated.slice(-500);
 store('studyos_generated_standard_v5',standardGenerated);
 return pool;
}
// v5: 無限一問一答。出題重みと新規生成は標準学習から独立。
const endlessStoreKey='studyos_endless_v5';
let endlessData=read(endlessStoreKey,{answered:0,correct:0,streak:0,bestByDay:{},stats:{},generated:[]});
let endless={active:false,format:'choice',question:null,selected:'',revealed:false,answered:0,correct:0,streak:0,started:0,activeStart:0,elapsed:0,subjectMs:{}};
const eNorm=s=>normalize(s).replace(/[。．.！!？?]/g,'');
function endlessPersist(){store(endlessStoreKey,endlessData)}
function verifiedGeneratedQuestion(){
  // 数式の計算はJavaScriptで正解を確定。文章・歴史・漢字の未検証AI生成は行わない。
  const type=Math.floor(Math.random()*5),a=1+Math.floor(Math.random()*10),b=1+Math.floor(Math.random()*10);
  let question,answer,level,unit,explanation;
  if(type===0){const x=Math.floor(Math.random()*10),y=Math.floor(Math.random()*(11-x));question=`${x} + ${y} = ?`;answer=String(x+y);level='小学1年';unit='たし算';explanation=`${x} + ${y} = ${answer} です。`}
  else if(type===1){const x=5+Math.floor(Math.random()*16),y=Math.floor(Math.random()*(x+1));question=`${x} − ${y} = ?`;answer=String(x-y);level='小学2年';unit='ひき算';explanation=`${x} − ${y} = ${answer} です。`}
  else if(type===2){question=`${a} × ${b} = ?`;answer=String(a*b);level='小学3年';unit='かけ算';explanation=`${a} × ${b} = ${answer} です。`}
  else if(type===3){const x=Math.floor(Math.random()*41)-20,y=Math.floor(Math.random()*31)-15;question=`x + (${y}) = ${x+y} のとき、x = ?`;answer=String(x);level='中学1年';unit='一次方程式';explanation=`両辺から (${y}) を引くと x = ${x} です。`}
  else {const x=2+Math.floor(Math.random()*13),y=2+Math.floor(Math.random()*13);question=`${x}² − ${y}² = ?`;answer=String(x*x-y*y);level='高校1年';unit='数学I・数と式';explanation=`${x*x} − ${y*y} = ${answer} です。`}
  const key='gen|'+question;return {id:key,subject:'math',level,unit,question,answer,explanation,choices:[],verified:true,origin:'generated'};
}
function endlessAllQuestions(){const known=[...BANK,...customQuestions.filter(q=>q.answer&&q.question),...endlessData.generated];const seen=new Set();return known.filter(q=>{const key=q.subject+'|'+eNorm(q.question)+'|'+eNorm(q.answer);if(seen.has(key))return false;seen.add(key);return !!q.answer})}
function endlessWeight(q){const st=endlessData.stats[questionId(q)]||{correct:0,wrong:0,skipped:0};const elementary=/^小学|^小学校/.test(q.level);return Math.max(.2,(elementary?.20:1)*(6+st.wrong*4+st.skipped*5-st.correct*1.5))}
function endlessChoose(){let available=endlessAllQuestions().filter(q=>q.id!==endless.question?.id);
 // 検証可能な計算テンプレートを使って新規問題を補充。生成問題も重複チェック。
 if(Math.random()<.32||available.length<5){for(let i=0;i<30;i++){const candidate=verifiedGeneratedQuestion();if(!endlessAllQuestions().some(q=>eNorm(q.question)===eNorm(candidate.question)&&q.subject===candidate.subject)){endlessData.generated.push(candidate);if(endlessData.generated.length>250)endlessData.generated.shift();endlessPersist();available.push(candidate);break}}}
 if(!available.length)return null;const weights=available.map(endlessWeight),sum=weights.reduce((a,b)=>a+b,0);let r=Math.random()*sum;return available[weights.findIndex(w=>(r-=w)<0)];}
function endlessChoices(q){let choices=(q.choices||[]).filter(x=>x&&eNorm(x)!==eNorm(q.answer));if(choices.length<3){const same=endlessAllQuestions().filter(x=>x.subject===q.subject&&x.id!==q.id&&x.answer&&eNorm(x.answer)!==eNorm(q.answer)).map(x=>x.answer);choices.push(...same);}
 if(choices.length<3&&q.subject==='math'&&Number.isFinite(Number(q.answer))){const a=Number(q.answer);choices.push(String(a+1),String(a-1),String(a+2),String(a-2));}
 choices=[...new Set(choices)].filter(x=>eNorm(x)!==eNorm(q.answer)).slice(0,3);if(choices.length<3){const fallback=['不明','該当なし','その他','未定'];choices.push(...fallback.filter(x=>eNorm(x)!==eNorm(q.answer)&&!choices.includes(x)));choices=choices.slice(0,3)}
 return [q.answer,...choices].sort(()=>Math.random()-.5);
}
function renderEndlessSummary(){const el=$('endlessCumulative');if(el)el.textContent=`累計 ${endlessData.answered}問 / 正解 ${endlessData.correct}問 / 正答率 ${endlessData.answered?(endlessData.correct/endlessData.answered*100).toFixed(1)+'%':'—'}`}
function renderEndless(){const day=dayKey(now());$('endlessAnswered').textContent=endless.answered;$('endlessCorrect').textContent=endless.correct;$('endlessAccuracy').textContent=endless.answered?(endless.correct/endless.answered*100).toFixed(1)+'%':'—';$('endlessStreak').textContent=endless.streak;$('endlessBest').textContent=endlessData.bestByDay[day]||0;$('endlessChoice').classList.toggle('selected',endless.format==='choice');$('endlessInput').classList.toggle('selected',endless.format==='input');$('endlessStart').classList.toggle('hidden',endless.active);$('endlessStop').classList.toggle('hidden',!endless.active);$('endlessQuestionWrap').classList.toggle('hidden',!endless.active);$('endlessSkip').classList.toggle('hidden',!endless.active||endless.revealed);$('endlessSubmit').classList.toggle('hidden',!endless.active||endless.revealed);$('endlessNext').classList.toggle('hidden',!endless.active||!endless.revealed);$('endlessStatus').textContent=endless.active?'学習中':'準備完了';if(!endless.active||!endless.question)return;
 const q=endless.question;$('endlessCategory').textContent=`${NAMES[q.subject]||q.subject} / ${q.level} / ${q.unit}`;$('endlessQuestion').textContent=q.question;
 const media=$('endlessMedia');media.replaceChildren();if(q.image){const img=document.createElement(q.imageType==='application/pdf'?'iframe':'img');img.src=q.image;img.className=q.imageType==='application/pdf'?'problem-pdf':'problem-image';media.append(img)}
 const area=$('endlessAnswerArea');area.replaceChildren();if(!endless.revealed){const choices=endless.format==='choice'?endlessChoices(q):null;if(choices){const wrap=document.createElement('div');wrap.className='answers';for(const c of choices){const b=document.createElement('button');b.className='answer-option'+(endless.selected===c?' selected':'');b.textContent=c;b.onclick=()=>{endless.selected=c;wrap.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b))};wrap.append(b)}area.append(wrap)}else{const input=document.createElement('input');input.placeholder='答えを入力';input.value=endless.selected;input.oninput=()=>{endless.selected=input.value};input.onkeydown=e=>{if(e.key==='Enter')endlessSubmit()};area.append(input)}}
 const fb=$('endlessFeedback');fb.className='';fb.textContent='';if(endless.revealed){const ok=endless.outcome==='correct';fb.className=ok?'good':'bad';fb.textContent=`${ok?'正解！':endless.outcome==='skipped'?'未回答':'不正解'}　正解：${q.answer}\n${q.explanation||''}`}
}
function endlessStart(){if(endless.active)return;if(quiz){alert('進行中の学習・テストを終了してから開始してください。');return}if(timerElapsed()>1000){alert('二重計上を避けるため、先にタイマーを記録して終了してください。');return}endless.active=true;endless.started=now();endless.activeStart=now();endless.elapsed=0;endless.answered=0;endless.correct=0;endless.streak=0;endless.subjectMs={};endless.question=null;endlessNext()}
function endlessNext(){if(!endless.active)return;endless.question=endlessChoose();endless.selected='';endless.revealed=false;endless.questionStart=now();if(!endless.question){endlessStop();alert('出題できる問題がありません。');return}renderEndless()}
function endlessSubmit(skip=false){if(!endless.active||endless.revealed)return;if(!skip&&!String(endless.selected).trim()){alert('回答を入力・選択するか「分からない」を押してください。');return}const q=endless.question,ok=!skip&&eNorm(endless.selected)===eNorm(q.answer),id=questionId(q),st=endlessData.stats[id]||{correct:0,wrong:0,skipped:0};if(skip)st.skipped++;else if(ok)st.correct++;else st.wrong++;endlessData.stats[id]=st;endlessData.answered++;endless.answered++;if(ok){endlessData.correct++;endless.correct++;endless.streak++}else endless.streak=0;const today=dayKey(now());endlessData.bestByDay[today]=Math.max(endlessData.bestByDay[today]||0,endless.streak);endless.outcome=skip?'skipped':ok?'correct':'wrong';endless.revealed=true;endless.subjectMs[q.subject]=(endless.subjectMs[q.subject]||0)+Math.max(0,now()-endless.questionStart);endlessPersist();renderEndless()}
function endlessStop(){if(!endless.active)return;const elapsed=Math.max(0,now()-endless.activeStart);endless.active=false;if(endless.answered){const date=now();records.unshift({id:date,date,kind:'endless',subject:'mixed',total:endless.answered,correct:endless.correct,unanswered:0,format:endless.format,elapsed});store('studyos_records',records);const subjectTotal=Object.values(endless.subjectMs).reduce((a,b)=>a+b,0);for(const [subject,ms] of Object.entries(endless.subjectMs)){sessions.unshift({date,subject,ms:Math.round(elapsed*ms/Math.max(1,subjectTotal)),source:'endless'})}store('studyos_sessions',sessions)}renderEndless();renderHome()}
$('endlessChoice').onclick=()=>{endless.format='choice';endless.selected='';renderEndless()};$('endlessInput').onclick=()=>{endless.format='input';endless.selected='';renderEndless()};$('endlessStart').onclick=endlessStart;$('endlessStop').onclick=endlessStop;$('endlessSubmit').onclick=()=>endlessSubmit(false);$('endlessSkip').onclick=()=>endlessSubmit(true);$('endlessNext').onclick=endlessNext;


// v7: 公開過去問ソース案内・PDF文字抽出・一括取り込み。スキャンOCR/サイト横断自動取得は未実装。
let wizardStep=0,certAction='practice',unlimitedTime=false,pastExams=read('studyos_past_exams_v6',[]),selectedPastKey='';
const pastKey=(type,grade,year,round)=>[type,grade,Number(year),Number(round)].join('|');
function setWizardStep(n){wizardStep=Math.max(0,Math.min(3,n));renderWizard()}
function renderWizard(){document.querySelectorAll('.wizard-panel').forEach(el=>el.classList.toggle('hidden',Number(el.dataset.step)!==wizardStep));$('wizardSteps').textContent='STEP '+(wizardStep+1)+' / 4';$('wizardBack').classList.toggle('hidden',wizardStep===0);$('wizardNext').classList.toggle('hidden',wizardStep===3);$('startQuiz').classList.toggle('hidden',wizardStep!==3);$('certOptions').classList.toggle('hidden',mode!=='cert');$('subjectPanel').classList.toggle('hidden',mode==='cert');$('pastExamPanel').classList.toggle('hidden',!(mode==='cert'&&certAction==='past'));$('unitPanel').classList.toggle('hidden',mode==='cert'&&certAction==='past');$('countWrap').classList.toggle('hidden',mode==='cert'&&certAction==='past');$('testTimeWrap').classList.toggle('hidden',mode==='study');$('formatWrap').classList.toggle('hidden',mode!=='study');if(wizardStep===1)renderSubjectCards();if(wizardStep===2){renderUnitCards();renderPastExamList()}refreshAvailability()}
function skillKey(q){return [q.subject,q.unit].join('|')}
function progressFor(subject,unit){const catalog=CURRICULUM[subject]||{};const names=[...new Set(Object.values(catalog).flat())];const relevant=unit&&unit!=='all'?[unit]:names;const data=[...BANK,...customQuestions,...standardGenerated];const values=relevant.map(u=>{const qs=data.filter(q=>q.subject===subject&&q.unit===u);if(!qs.length)return 0;const samples=qs.map(q=>{const st=questionStats[questionId(q)]||{};const n=(st.correct||0)+(st.wrong||0)+(st.skipped||0);if(!n)return 0;const accuracy=(st.correct||0)/n;return Math.min(100,Math.round((n>=5?70:n>=3?50:25)*accuracy+(n>=5&&accuracy>=.8?15:0)))});return Math.round(samples.reduce((a,b)=>a+b,0)/samples.length)});return values.length?Math.round(values.reduce((a,b)=>a+b,0)/values.length):0}
function progressButton(name,p,active,click,sub=''){const b=document.createElement('button');b.className='progress-option'+(active?' selected':'');const top=document.createElement('div');top.className='progress-option-top';const title=document.createElement('strong');title.textContent=name;const percent=document.createElement('span');percent.textContent=p+'%';top.append(title,percent);const bar=document.createElement('div');bar.className='progress';const fill=document.createElement('div');fill.style.width=p+'%';bar.append(fill);b.append(top,bar);if(sub){const small=document.createElement('small');small.textContent=sub;b.append(small)}b.onclick=click;return b}
function renderSubjectCards(){const list=$('subjectCards');list.replaceChildren();for(const [key,name] of Object.entries(NAMES))list.append(progressButton(name,progressFor(key),$('subject').value===key,()=>{$('subject').value=key;updateLevels();renderSubjectCards();renderUnitCards()}))}
function renderUnitCards(){const list=$('unitCards');list.replaceChildren();const s=$('subject').value;if(!s)return;const catalog=CURRICULUM[s]||{};const all=[...new Set(Object.values(catalog).flat().concat(sourceBank().filter(q=>q.subject===s).map(q=>q.unit)))];list.append(progressButton('すべての単元',progressFor(s),$('unit').value==='all',()=>{$('level').value='all';updateUnits();$('unit').value='all';renderUnitCards();refreshAvailability()}));for(const u of all){const grades=Object.entries(catalog).filter(([,units])=>units.includes(u)).map(([grade])=>grade);if($('level').value!=='all'&&!grades.includes($('level').value)&&!sourceBank().some(q=>q.subject===s&&q.level===$('level').value&&q.unit===u))continue;list.append(progressButton(u,progressFor(s,u),$('unit').value===u,()=>{$('level').value='all';updateUnits();$('unit').value=u;renderUnitCards();refreshAvailability()},grades.join('・')))}}
function sortedPastSets(type,grade){const m=new Map();for(const q of pastExams){if(q.certType!==type||q.certGrade!==grade)continue;const k=pastKey(q.certType,q.certGrade,q.year,q.round);if(!m.has(k))m.set(k,[]);m.get(k).push(q)}return [...m.entries()].sort((a,b)=>{const x=a[1][0],y=b[1][0];return Number(x.year)-Number(y.year)||Number(x.round)-Number(y.round)})}
function pastSelectedQuestions(){return pastExams.filter(q=>pastKey(q.certType,q.certGrade,q.year,q.round)===selectedPastKey ).sort((a,b)=>Number(a.order)-Number(b.order))}
function renderPastExamList(){const list=$('pastExamList');if(!list)return;list.replaceChildren();const sets=sortedPastSets($('certType').value,$('certGrade').value);if(!sets.some(([k])=>k===selectedPastKey))selectedPastKey=sets[0]?.[0]||'';if(!sets.length){list.textContent='この級の過去問は未登録です。過去問ライブラリから追加できます。';refreshAvailability();return}for(const [key,items] of sets){const first=items[0];const total=Number(first.expectedTotal)||null;const b=document.createElement('button');b.className='progress-option'+(selectedPastKey===key?' selected':'');b.textContent=`${first.year}年度 第${Number(first.round)}回　${items.length}問登録${total?' / 全'+total+'問':''}${total&&items.length<total?'（一部不足）':''}`;b.onclick=()=>{selectedPastKey=key;renderPastExamList();refreshAvailability()};list.append(b)}refreshAvailability()}
function renderPastLibrary(){const list=$('pastLibrary');list.replaceChildren();const groups=new Map();for(const q of pastExams){const key=pastKey(q.certType,q.certGrade,q.year,q.round);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(q)}const entries=[...groups.values()].sort((a,b)=>a[0].certType.localeCompare(b[0].certType,'ja')||a[0].certGrade.localeCompare(b[0].certGrade,'ja')||a[0].year-b[0].year||a[0].round-b[0].round);if(!entries.length){list.textContent='まだ過去問が登録されていません。';return}for(const qs of entries){const q=qs[0];const div=document.createElement('div');div.className='past-row';const title=document.createElement('strong');title.textContent=`${CERTS[q.certType]?.name||q.certType} ${q.certGrade} / ${q.year}年度 第${q.round}回`;const sub=document.createElement('small');sub.textContent=`登録済み ${qs.length}問 / 解答登録済み ${qs.filter(x=>x.answer).length}問${q.expectedTotal?' / 公式総数 '+q.expectedTotal+'問':''}`;const btn=document.createElement('button');btn.className='outline';btn.textContent='この回に追加';btn.onclick=()=>{$('pastType').value=q.certType;updatePastGrades();$('pastGrade').value=q.certGrade;$('pastYear').value=q.year;$('pastRound').value=q.round;$('pastTotal').value=q.expectedTotal||'';$('pastOrder').value=Math.max(...qs.map(x=>Number(x.order)||0))+1;window.scrollTo(0,0)};div.append(title,sub,btn);list.append(div)}}
function updatePastGrades(){const type=$('pastType').value;options($('pastGrade'),CERTS[type].grades.map(g=>[g,g]))}
async function savePastProblem(){const type=$('pastType').value,grade=$('pastGrade').value,year=Number($('pastYear').value),round=Number($('pastRound').value),order=Number($('pastOrder').value),expectedTotal=Number($('pastTotal').value)||null,question=$('pastQuestion').value.trim(),answer=$('pastAnswer').value.trim(),explanation=$('pastExplanation').value.trim();if(!Number.isInteger(year)||year<1900||year>2100||!Number.isInteger(round)||round<1||!Number.isInteger(order)||order<1){alert('年度・回・問題番号を確認してください。');return}if(!question&&!$('pastFile').files[0]){alert('問題文か資料が必要です。');return}try{const image=await fileAsData($('pastFile').files[0]),answerImage=await fileAsData($('pastAnswerFile').files[0]);const existing=pastExams.find(q=>q.certType===type&&q.certGrade===grade&&q.year===year&&q.round===round&&q.order===order);if(existing&&!confirm('この実施回の同じ問題番号が登録されています。上書きしますか？'))return;const obj={addStandard:$('pastAddStandard').checked,id:existing?.id||'past_'+Date.now()+'_'+Math.random().toString(36).slice(2,7),subject:type,level:grade,unit:'過去問',certType:type,certGrade:grade,year,round,order,expectedTotal,question,answer,explanation,image:image||existing?.image||null,imageType:$('pastFile').files[0]?.type||existing?.imageType||'',answerImage:answerImage||existing?.answerImage||null,answerImageType:$('pastAnswerFile').files[0]?.type||existing?.answerImageType||'',choices:[]};if(existing)pastExams=pastExams.map(q=>q.id===existing.id?obj:q);else pastExams.push(obj);for(const q of pastExams){if(q.certType===type&&q.certGrade===grade&&q.year===year&&q.round===round)q.expectedTotal=expectedTotal||q.expectedTotal||null}store('studyos_past_exams_v6',pastExams);refreshAvailability();$('pastQuestion').value='';$('pastAnswer').value='';$('pastExplanation').value='';$('pastFile').value='';$('pastAnswerFile').value='';$('pastOrder').value=order+1;$('pastStatus').textContent='保存しました。問題番号 '+order+' を登録しました。';renderPastLibrary();renderPastExamList()}catch(e){alert('保存できませんでした：'+e.message)}}
function initV6(){options($('pastType'),Object.entries(CERTS).map(([key,v])=>[key,v.name]));$('pastType').onchange=updatePastGrades;updatePastGrades();$('pastSave').onclick=savePastProblem;initOfficialSources();$('goEndless').onclick=()=>page('endless');$('wizardBack').onclick=()=>setWizardStep(wizardStep-1);$('wizardNext').onclick=()=>{if(wizardStep===2&&mode==='cert'&&certAction==='past'&&!selectedPastKey){alert('過去問を選択してください。');return}setWizardStep(wizardStep+1)};$('certPractice').onclick=()=>{certAction='practice';$('certPractice').classList.add('selected');$('certPast').classList.remove('selected');renderWizard()};$('certPast').onclick=()=>{certAction='past';$('certPast').classList.add('selected');$('certPractice').classList.remove('selected');renderWizard()};$('timeLimited').onclick=()=>{unlimitedTime=false;renderTimeChoice()};$('timeUnlimited').onclick=()=>{unlimitedTime=true;renderTimeChoice()};$('openPastManager').onclick=()=>page('pastmanager');renderTimeChoice();renderWizard()}
function renderTimeChoice(){$('timeLimited').classList.toggle('selected',!unlimitedTime);$('timeUnlimited').classList.toggle('selected',unlimitedTime);$('minutesWrap').classList.toggle('hidden',unlimitedTime)}

// v8 Official sources and text-based PDF import; shared past-exam question bank. No server-side scraping or OCR.
const OFFICIAL_SOURCES={
 japanese:[{name:'漢検 公式・過去問題PDF（問題例）',url:'https://www.kanken.or.jp/kanken/grades/sample/',note:'公式掲載分のみ。著作権・利用条件を確認してください。'}],
 english:[{name:'英検 公式・過去問／試験内容',url:'https://www.eiken.or.jp/eiken/exam/',note:'級を選択し、公開されている年度・回のPDFを保存。'}],
 math:[{name:'数検 公式サイト',url:'https://www.su-gaku.net/',note:'公開問題・サンプルの提供範囲を公式サイトで確認。'}],
 it:[{name:'IPA 公式・過去問題',url:'https://www.ipa.go.jp/shiken/mondai-kaiotu/',note:'公開問題の出典（年度・試験区分・問番号）を明記。'}]
};
let pendingSource=[];
function initOfficialSources(){
 options($('sourceType'),Object.entries(CERTS).map(([k,v])=>[k,v.name]));
 $('sourceType').onchange=()=>{options($('sourceGrade'),CERTS[$('sourceType').value].grades.map(g=>[g,g]));renderOfficialSources()};
 $('sourceType').onchange();
 $('fetchSourcePdf').onclick=async()=>{
  const url=$('sourcePdfUrl').value.trim();if(!/^https:\/\//i.test(url)){sourceStatus('HTTPSのPDF URLを入力してください。');return}
  sourceStatus('公開PDFの取得を試しています…');
  try{const res=await fetch(url,{mode:'cors'});if(!res.ok)throw Error('HTTP '+res.status);const blob=await res.blob();if(blob.size>15*1024*1024)throw Error('PDFが15MBを超えています');const file=new File([blob],'official.pdf',{type:'application/pdf'});await prepareSource(file,$('sourceAnswerPdf').files[0]);}
  catch(e){sourceStatus('ブラウザから直接取得できませんでした（公開元のCORS制限など）。公式ページでPDFを保存し「保存した問題PDF」から読み込んでください。 '+e.message)}
 };
 $('parseSourcePdf').onclick=async()=>{const file=$('sourcePdf').files[0];if(!file){sourceStatus('問題PDFを選択してください。');return}await prepareSource(file,$('sourceAnswerPdf').files[0])};
 $('saveSourceQuestions').onclick=saveParsedSource;
}
function sourceStatus(message){$('sourceStatus').textContent=message}
function renderOfficialSources(){const el=$('officialSourceLinks');el.replaceChildren();for(const s of OFFICIAL_SOURCES[$('sourceType').value]||[]){const p=document.createElement('p'),a=document.createElement('a');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=s.name+' ↗';p.append(a,document.createTextNode(' — '+s.note));el.append(p)}}
async function extractPdfPages(file){
 if(!window.pdfjsLib)throw Error('PDF解析ライブラリを読み込めません。インターネット接続を確認してください。');
 if(file.size>15*1024*1024)throw Error('PDFは15MB以下にしてください。');
 window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
 const bytes=new Uint8Array(await file.arrayBuffer());const doc=await pdfjsLib.getDocument({data:bytes}).promise;
 const pages=[];for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i),content=await page.getTextContent();let text='';let prevY=null;for(const item of content.items){if(!item.str)continue;const y=item.transform?.[5];if(prevY!==null&&Math.abs(y-prevY)>4)text+='\n';else if(text&&!text.endsWith('\n'))text+=' ';text+=item.str;prevY=y}pages.push(text.trim())}return pages;
}
function splitQuestions(pages){const items=[];let sequence=1;
 for(let i=0;i<pages.length;i++){
  const text=pages[i];if(!text)continue;
  const parts=text.split(/(?=(?:^|\n)\s*(?:問\s*\d{1,3}|第\s*\d{1,3}\s*問|\d{1,3}\s*[.．、])\s*)/m).map(s=>s.trim()).filter(Boolean);
  const blocks=parts.length>1?parts:[text];
  for(const block of blocks){if(block.length<8)continue;const match=block.match(/^(?:問\s*(\d{1,3})|第\s*(\d{1,3})\s*問|(\d{1,3})\s*[.．、])/);const n=match?Number(match[1]||match[2]||match[3]):sequence;items.push({order:n,question:block,answer:'',explanation:'',page:i+1});sequence=Math.max(sequence+1,n+1)}
 }
 return items;
}
async function prepareSource(file,answerFile){
 sourceStatus('PDFの文字を解析中…');$('saveSourceQuestions').classList.add('hidden');
 try{
  const pages=await extractPdfPages(file);pendingSource=splitQuestions(pages);
  if(!pendingSource.length)throw Error('文字が抽出できません。画像だけのPDFは手動登録してください。');
  if(answerFile){const answerPages=await extractPdfPages(answerFile);const answerText=answerPages.join('\n');for(const item of pendingSource){const re=new RegExp('(?:問\\s*'+item.order+'|第\\s*'+item.order+'\\s*問|(?:^|\\n)\\s*'+item.order+'\\s*[.．、])\\s*([^\\n]{1,100})','m');const m=answerText.match(re);if(m)item.answer=m[1].trim()}}
  renderSourcePreview();sourceStatus(pendingSource.length+'件の候補を抽出しました。問題の区切り・解答を確認してから保存してください。PDFのレイアウトにより誤分割される場合があります。');
 }catch(e){pendingSource=[];$('sourcePreview').replaceChildren();sourceStatus('解析できませんでした：'+e.message)}
}
function renderSourcePreview(){const wrap=$('sourcePreview');wrap.replaceChildren();const head=document.createElement('h4');head.textContent='抽出した問題候補（保存前に編集）';wrap.append(head);
 pendingSource.forEach((q,i)=>{const card=document.createElement('div');card.className='past-row';const label=document.createElement('label');label.textContent='候補 '+(i+1)+' ／ PDF '+q.page+'ページ';card.append(label);
 const order=document.createElement('input');order.type='number';order.min='1';order.value=q.order;order.title='問題番号';order.oninput=()=>q.order=Number(order.value);card.append(order);
 const question=document.createElement('textarea');question.rows=4;question.value=q.question;question.oninput=()=>q.question=question.value;card.append(question);
 const answer=document.createElement('input');answer.placeholder='正解（空欄なら自己採点）';answer.value=q.answer;answer.oninput=()=>q.answer=answer.value;card.append(answer);
 const remove=document.createElement('button');remove.className='outline';remove.textContent='この候補を除外';remove.onclick=()=>{pendingSource.splice(i,1);renderSourcePreview()};card.append(remove);wrap.append(card)});
 $('saveSourceQuestions').classList.toggle('hidden',!pendingSource.length);
}
function saveParsedSource(){const type=$('sourceType').value,grade=$('sourceGrade').value,year=Number($('sourceYear').value),round=Number($('sourceRound').value);
 if(!Number.isInteger(year)||year<1900||year>2100||!Number.isInteger(round)||round<1){sourceStatus('年度・回数を確認してください。');return}
 let added=0,updated=0;for(const item of pendingSource){if(!item.question.trim()||!Number.isInteger(item.order)||item.order<1)continue;
 const existing=pastExams.find(q=>q.certType===type&&q.certGrade===grade&&q.year===year&&q.round===round&&q.order===item.order);
 if(existing){if(existing.question&&existing.answer)continue;existing.question=existing.question||item.question;existing.answer=existing.answer||item.answer;existing.addStandard=existing.addStandard!==false||$('sourceAddStandard').checked;updated++;continue}
 pastExams.push({id:'past_pdf_'+Date.now()+'_'+Math.random().toString(36).slice(2,9),subject:type,level:grade,unit:'過去問',certType:type,certGrade:grade,year,round,order:item.order,expectedTotal:null,addStandard:$('sourceAddStandard').checked,question:item.question,answer:item.answer,explanation:item.explanation,image:null,imageType:'',answerImage:null,answerImageType:'',choices:[],source:'PDFから抽出・要確認'});added++}
 try{store('studyos_past_exams_v6',pastExams)}catch(e){sourceStatus('保存容量を超えました。バックアップを取ってデータを整理してください。');return}
 sourceStatus('保存しました。新規'+added+'問、既存の不足情報を補完'+updated+'問。解答付きの問題は検定学習の標準問題にも反映されます（追加設定がオンの場合）。');pendingSource=[];$('sourcePreview').replaceChildren();$('saveSourceQuestions').classList.add('hidden');renderPastLibrary();renderPastExamList();refreshAvailability();
}

